components.css:
.ds-category-control {
  min-width: 0;
  margin: 24px 0 0;
  padding: 0 0 18px;
  border: 0;
  border-bottom: 1px solid var(--line);
}

.ds-category-control legend {
  padding: 0;
  font-size: 0.88rem;
  font-weight: 750;
}

#ds-category-help {
  margin: 6px 0 12px;
  color: var(--muted);
  font-size: 0.78rem;
  line-height: 1.5;
}

.ds-category-options {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.ds-category-option {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 44px;
  max-width: 100%;
  padding: 8px 10px;
  border: 1px solid var(--line);
  border-radius: var(--radius-control);
  color: var(--ink);
  font-size: 0.82rem;
  line-height: 1.5;
  cursor: pointer;
}

.ds-category-option input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  opacity: 0;
  cursor: pointer;
}

.ds-category-check {
  width: 14px;
  height: 14px;
  flex: 0 0 auto;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
  visibility: hidden;
}

.ds-category-option:has(input:checked) {
  border-color: var(--green);
  color: var(--green-dark);
  background: var(--surface);
}

.ds-category-option:has(input:checked) .ds-category-check {
  visibility: visible;
}

.ds-category-option:hover {
  border-color: var(--muted);
}

.ds-category-option:has(input:focus-visible) {
  outline: 3px solid var(--green);
  outline-offset: 2px;
}
